from review import card,save,DATE
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2103';_,c=card(i);refs=c['references'];refs[0]['locator']='STACS 2024, article 4: graph/weight conventions in Section 1, Theorems 1–2 and Conjecture 10 read. S_{t,t,t} is excluded as an induced subgraph. The proved theorem additionally excludes a fixed biclique as a subgraph.'
save(i,dict(title='Maximum-weight independent set with no long induced claw or large clique',formal='For every fixed pair of integers t≥1 and r≥2, is there a deterministic polynomial-time algorithm that, given a vertex-weighted graph containing neither an induced S_{t,t,t} nor a clique K_r, computes the maximum possible weight of an independent set?',definitions='The input is a finite undirected simple graph G=(V,E), with n=|V|, and integer weights w:V→N. An independent set I⊆V contains no adjacent pair, and its weight is Σ_{v∈I}w(v), with the empty set having weight zero. S_{t,t,t} is the tree formed by three paths of t edges sharing one common endpoint and otherwise having disjoint vertices; it has 3t+1 vertices and one degree-three center. An induced copy requires exactly the edges of that tree among its selected vertices. K_r is the complete graph on r vertices, so excluding it means every clique has size at most r−1. The algorithm is promised both exclusions. For each fixed t,r its running time must be at most n^{c(t,r)} times a constant depending on t,r, with arithmetic and comparisons on weights counted at unit cost as in the source. No bounded maximum degree, excluded biclique, or supplied graph decomposition is assumed. This is polynomial time for each fixed t,r, not necessarily a fixed-parameter bound f(t,r)n^C with universal C.',question_type='yes_no',answer_criterion='Give such an exact polynomial-time algorithm for every fixed t,r, or refute the universal algorithmic assertion, for example by an appropriate conditional hardness result for one fixed pair. Approximation or an algorithm requiring an additional bounded-degree or biclique exclusion promise does not establish the conjecture.',context_blocks=[b('A long claw is an induced branching pattern','For t=1, S_{t,t,t} is the ordinary four-vertex claw K_{1,3}. Increasing t allows longer arms. Edges between selected arm vertices can destroy an induced copy, so the exclusion is different from forbidding the tree as any subgraph.'),b('The known theorem assumes more sparsity','The source proves polynomial-time maximum-weight independent set when S_{t,t,t} is excluded as an induced subgraph and some fixed complete bipartite graph K_{s,s} is excluded as a subgraph. The conjecture asks to retain only a bound on clique size.', 'primary'),b('Small cliques do not force few edges','For t≥2, arbitrarily large complete bipartite graphs satisfy these induced-tree and triangle exclusions while having quadratically many edges. The conjectured class therefore extends beyond the sparse graph setting of the proved result.'),b('The output is an exact optimum','Weights can make a smaller independent set preferable to a larger one. The target is the maximum sum of weights, not only the maximum number of mutually nonadjacent vertices.')],why='Would extend exact independent-set algorithms from degree- or biclique-restricted graphs to a substantially broader hereditary class defined by a branching pattern and clique size.',progress=[dict(date='2024',text='The source gives polynomial-time algorithms under bounded degree or fixed-biclique exclusion, and states Conjecture 10 for the clique-only restriction.',citation='primary')],references=refs,status='source_open',status_note='The complete source conjecture and algorithmic/weight conventions were checked, together with arXiv:2309.16995v3 and later-result searches through 12 September 2026. No resolution for all fixed t,r was located.',model_self_contained=True,requires_context=False,importance=imp(c,'An exact-algorithm boundary for maximum-weight independent set in hereditary graph classes.'),review_note='Restored the missing optimum-weight conclusion and induced-subgraph definitions. Preserved the unit-cost integer-weight convention and distinguished fixed-parameter polynomiality from an FPT claim.',working_summary=sm(['The input graph has no long induced three-armed claw and no clique above a fixed size.','The question asks for the exact maximum weight of a set of pairwise nonadjacent vertices in polynomial time.','The arm length and forbidden clique size are fixed constants.','Known algorithms also require bounded degree or exclusion of a fixed biclique.','Removing that extra sparsity requirement is the unresolved step.'],['primary'])),notes=['Recovered the full maximum-weight independent-set conjecture.','Defined the induced subdivided claw, clique promise, weights and fixed-parameter runtime convention.','Separated the known biclique-exclusion theorem from the weaker requested promise.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2309.16995','https://web.math.princeton.edu/~mchudnov/sparseclaws.pdf'])

i='TCS-2111';_,c=card(i);refs=c['references'];refs[0]['locator']='COLT 2024, PMLR 247, pp. 1364–1378: Theorem 1, its normalization and improper-learning discussion, comparison to prior work and final open question on PDF p. 13 read. Selected the explicitly highlighted nonnegative-output-weight special case.'
refs.append(dict(id='positive_algorithm',title='Small Covers for Near-Zero Sets of Polynomials and Learning Latent Variable Models',authors='Ilias Diakonikolas, Daniel M. Kane',year=2020,url='https://arxiv.org/abs/2012.07774',pdf_url='https://cseweb.ucsd.edu/~dakane/CoversPolynomials.pdf',locator='Section 1.4.2 and Theorem 4 read. Gives a quasipolynomial dependence on hidden-layer width for learning positive combinations of ReLUs, including a noisy relative-error formulation; used here in the normalized noiseless special case.'))
save(i,dict(title='Fully polynomial learning of positive ReLU networks under Gaussian inputs',formal='Is there a randomized learner with sample complexity and running time poly(d,k,1/ε) that, from noiseless independent examples (X,F(X)) with X∼N(0,I_d), learns every function F(x)=Σ_{i=1}^k w_i max{0,v_i·x}, where ||v_i||₂=1, w_i≥0 and Σ_i w_i≤1, to L₂ error at most ε with probability at least 9/10? The learner may be improper and must also output an efficiently evaluable hypothesis.',definitions='The ambient dimension d and number k of hidden ReLU units are positive integers supplied as bounds to the learner; 0<ε<1 is the desired accuracy. The activation ReLU(z)=max{0,z} has no bias or threshold shift here. The hidden unit vectors v_i and output coefficients w_i are unknown. Positivity concerns the output coefficients w_i, not the coordinates of v_i. The learner receives fresh i.i.d. samples from the stated distribution, not queries at chosen inputs. Its output H:R^d→R succeeds when (E_{X∼N(0,I_d)}[(H(X)−F(X))²])^{1/2}≤ε. The probability of at least 9/10 is over both samples and learner randomness; the error expectation uses a fresh Gaussian input. A single polynomial must bound sample count, running time, output-description size and evaluation cost as d,k,1/ε vary; k is not fixed. As in the source, examples have real coordinates and complexity is the arithmetic/sample complexity of the learning model, not an asserted finite-bit bound for exact Gaussian observations. H need not itself have k ReLU units. There is no separation, rank, conditioning or identifiability assumption on the v_i. Zero coefficients simply allow fewer than k active units.',question_type='yes_no',answer_criterion='Construct a learner satisfying the simultaneous polynomial dependence on d,k,1/ε for all normalized nonnegative-weight targets, or establish a valid hardness obstruction to that guarantee in the same sample-access model. A result only for fixed k, well-separated parameters, proper learning, or a restricted query algorithm does not resolve the full question.',context_blocks=[b('The task is prediction rather than parameter recovery','Different hidden networks can represent the same or nearly the same function. The learner only needs to predict F accurately on new Gaussian inputs; it need not reconstruct the original hidden vectors.'),b('The dependence on width is the open issue','A running time such as (dk/ε)^{O(k)} is polynomial when k is fixed, but its exponent grows with the width. The requested fully polynomial learner must use a fixed exponent even as the number of hidden units grows.'),b('Positive weights have a better known upper bound','The cited positive-weight algorithm runs in poly(dk/ε)+(k/ε)^{O(log²k)} time. This is quasipolynomial rather than polynomial in k and inverse accuracy. The 2024 source explicitly leaves the fully polynomial version open even in this special case.', 'positive_algorithm'),b('Known restricted-query barriers need careful scope','The 2024 paper discusses lower bounds for correlational statistical queries in the broader signed-weight class. Those bounds do not by themselves rule out a sample-based learner for this positive-weight question, and the learner here is not restricted to correlation queries.', 'primary')],why='Would determine whether a basic shallow neural-network class can be learned efficiently as both its dimension and width grow, without favorable assumptions on its hidden parameters.',progress=[dict(date='2020',text='Diakonikolas and Kane obtain quasipolynomial-width learning for positive combinations of ReLUs.',citation='positive_algorithm'),dict(date='2024',text='The COLT paper gives (dk/ε)^{O(k)} complexity for signed normalized networks and retains fully polynomial learning as open even for positive weights.',citation='primary')],references=refs,status='source_open',status_note='The source’s network normalization, Gaussian sample model, L₂ criterion and positive-weight question were checked, along with the earlier positive-weight theorem and later-result searches through 12 September 2026. No fully polynomial learner or matching general hardness resolution was located.',model_self_contained=True,requires_context=False,importance=imp(c,'A basic computational learnability question for shallow networks with unrestricted hidden directions.'),review_note='Recovered d,k,ε, passive Gaussian access, positive output coefficients, normalization and improper hypothesis convention. Selected the source’s highlighted positive-weight question and kept signed-network CSQ barriers separate.',working_summary=sm(['The target is a nonnegative weighted sum of k homogeneous ReLU units.','Examples have standard Gaussian inputs and exact labels.','The question asks for a learner polynomial in dimension, width and inverse prediction error simultaneously.','It may output any efficiently evaluable predictor and need not recover the hidden parameters.','The positive-weight upper bound still has a quasipolynomial dependence on width and accuracy.'],['primary','positive_algorithm'])),notes=['Restored the fully polynomial target and Gaussian, noiseless, normalized positive-weight model.','Defined root-mean-square error, success probability and improper prediction.','Separated constant-width algorithms and signed-network CSQ lower bounds from the selected question.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2307.12840','https://cseweb.ucsd.edu/~dakane/papers.html','https://arxiv.org/abs/2606.11130'])
